using System.Linq;
using static StrataLint.Scribe.DefinitionDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Hyperideal;

internal sealed class ActualCornerTransportDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual paired-corner paths lift nonnegative component weights with the occurrence bound 3B.",
        H("Weighted transport on actual tetrahedral face pairings"),
        Blocks(
            Paragraph(Text("T and S are arbitrary finite types, including empty types. K is an "
                + "arbitrary linearly ordered field. Corner=T x Fin(4), Occurrence=T x Fin(6), "
                + "and Slot=(T x Fin(4)) x Fin(3). Pairing has a fixed-point-free involution p "
                + "on whole faces and permutations sigma(x) with sigma(p(x))(sigma(x)(r))=r. "
                + "Face f omits vertex f; its corner slots list the other vertices increasingly. "
                + "Its edge slots are opposite those corners, in local order (12,13,14,34,24,23). "
                + "The SAME sigma transports corners and opposite edges.")),
            Paragraph(Text("b(i) is the actual source corner and J(i)=(p(i.face),sigma(i.face)(i.slot)). "
                + "Vertex is the equivalence closure quotient generated by b(i)~b(J(i)); GlobalEdge "
                + "is the corresponding quotient of actual opposite-edge occurrences. label and P "
                + "are these quotient maps. M(a,e) sums EVERY occurrence with P(o)=e; Q(a,c) sums "
                + "the three local edges incident at c. Self-gluing, loops and parallel pairings "
                + "retain their actual slot and occurrence multiplicities.")),
            Paragraph(Text("Follows(q,u,v,paths) means the slot list joins u to v with each next "
                + "source equal to the preceding actual target. Define integer chi(s,i) as "
                + "count(paths(s),i)-count(paths(s),J(i)), A(i)=sum_s w(s)chi(s,i), and "
                + "W(z)=sum_s indicator(label(u(s))=z)w(s). localLift(i) has coefficient +1/2 "
                + "on its opposite face edge, -1/2 on the other two face edges, and zero elsewhere. "
                + "The SAME vector a(o)=sum_i A(i)localLift(i,o) is used in every conclusion.")),
            Describe.Lean(
                DescribeId.Create("actual-paired-corner-weighted-lift"),
                DeclarationHandle.Create(
                    "D5/S3/Geometry/Hyperideal/ActualCornerTransport.actual_corner_transport"),
                H("Simple actual slot paths, component loads, conservation and the six-slot bound"),
                StatementSource.FromAuthor(F.Disp(Statement())),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Transport(q,u,v,w,B) asserts the existence of these shared "
                        + "slot lists. They follow the actual pairing, have no repeated corner, "
                        + "and are empty when u(s)=v(s). Each slot count is at most one. chi is "
                        + "antisymmetric, has absolute value at most one, and vanishes outside "
                        + "the source component. Its corner divergence is exactly "
                        + "indicator(u(s)=c)-indicator(v(s)=c). A(J(i))=-A(i), |A(i)|<=W(label(b(i))), "
                        + "M(a,e)=0, -Q(a,c)=sum_s w(s)(indicator(u(s)=c)-indicator(v(s)=c)), "
                        + "and |a(o)|<=3B for every occurrence.")),
                    Paragraph(Text("Mathlib supplies simple paths in the graph whose adjacency "
                        + "is an actual slot between distinct corners. A recursive lift selects "
                        + "actual slots for those steps, preserving parallel-slot witnesses. "
                        + "The signed counts telescope. Actual paired edge labels make "
                        + "M(localLift(J(i)))=M(localLift(i)); reindexing by J cancels the global "
                        + "edge sums. The local corner identity is Q(localLift(i))=-indicator(b(i)). "
                        + "Every local edge belongs to two faces with three slots each. All six "
                        + "half-coefficient contributions are counted before taking any quotient.")),
                    Paragraph(Text("B>=0 is not a premise. An existing occurrence gives an actual "
                        + "slot whose nonnegative absolute load is bounded by B. If T is empty, "
                        + "all classes and occurrences are empty and any B is allowed. Empty S "
                        + "and zero weights are included. Taking B=sum_s w(s) gives the total-weight "
                        + "specialization. Instantiating K with the rationals gives a rational vector.")),
                    Paragraph(Text("For component averaging, C(z) is the actual corner fiber, "
                        + "F(z)=card(C(z))>0 for every existing quotient class, and D(z)=sum_C(z) d(c). "
                        + "Index ALL ordered pairs in each fiber, including diagonal pairs, with "
                        + "w(z,u,v)=tau*d(v)/F(z), d>=0 and tau>=0. Their exact source mass is "
                        + "tau*D(z). With D(z)<=Dmax the SAME construction has "
                        + "|A(i)|<=tau*D(label(b(i))), |a(o)|<=3*tau*Dmax, and "
                        + "-Q(a,c)=tau*(D(label(c))/F(label(c))-d(c)). Subtracting the target sum "
                        + "tau*d(c) from the source sum tau*D(label(c))/F(label(c)) gives this profile.")),
                    Paragraph(Text("The strictification application is Lemma 42.1 of docs/develop/theory/CFMP_GEOMETRIC_REALIZATION.md, with the occurrence maps of Section 41 and the actual pairing of supplemental Lemma 42.3. The application uses exactly the Pairing q, its b and J, the functions faceVertex, faceEdge and endpoints, and both full equivalence-closure quotients defined in D5/S3/Geometry/Hyperideal/ActualCornerTransport.lean. In particular, a prescribed equation M(a0)=k is preserved by proving M(a)=M(a0); no additional boundary labeling replaces the actual corner quotient.")),
                    Paragraph(Text("For the necessary conservation law, attach to local edge j the two-element multiset E0(j) of its endpoints. For every face f and opposite slot r, E0(faceEdge(f,r)) is the image under faceVertex(f) of the two slots other than r. A permutation sigma maps that complement to the complement of sigma(r). Push these finite identities forward by the actual quotient corner label. The paired corner relations identify each image with its target image, so the endpoint-label multiset E(o) is unchanged by an actual paired-edge generator, and hence by reflexivity, symmetry and transitivity of the full edge equivalence closure. It therefore descends to a two-element multiset E(e) on each actual global edge.")),
                    Paragraph(Text("Let n(z,e) be the multiplicity of z in E(e). Then 0<=n(z,e)<=2, and n(z,P(o)) is the sum of the two endpoint-label indicators. If the endpoint labels agree, their multiplicity is two. This construction uses a multiset, including for loops and self-gluings. A set of endpoints would discard that multiplicity. The local endpoints themselves are distinct in Fin(4); separating their two local incidence indicators and reordering finite sums gives, for every arbitrary signed vector h over K, sum_{label(c)=z} Q(h,c)=sum_e n(z,e)M(h,e). No sign restriction on h is used.")),
                    Paragraph(Text("For any a and a0 with the same M, this identity makes sum_{label(c)=z}(1-Q(a,c)) equal to the corresponding sum for a0. Every actual quotient class has a representative, so each corner fiber is nonempty. If every Q(a,c)<1, its finite sum of positive deficits is positive. Thus D(z)>0 is necessary for any strict competitor, with no assumption that the competitor arose from the transport construction.")),
                    Paragraph(Text("For sufficiency, suppose a0(o)>0 and d0(c)=1-Q(a0,c)>=0. When T is nonempty, the finite occurrence domain has an attained minimum m=min_o a0(o)>0. The actual vertex quotient is also nonempty and finite; if every D(z)=sum_{label(c)=z}d0(c)>0, its attained maximum Dstar=max_z D(z) is positive. Choose 0<tau<=min(1/2,m/(6*Dstar)). Apply actual_corner_transport over K to all actual same-fiber ordered pairs (u,v), including u=v, with w(u,v)=tau*d0(v)/F(label(u)) and B=tau*Dstar. The same paths, signed counts, loads and occurrence lift delta occur in every following equation; diagonal pairs have empty paths.")),
                    Paragraph(Text("The source and target sums give -Q(delta,c)=tau*(D(label(c))/F(label(c))-d0(c)), while M(delta)=0 and |delta(o)|<=3*tau*Dstar. For a_tau=a0+delta, linearity gives M(a_tau)=M(a0) and 1-Q(a_tau,c)=(1-tau)*d0(c)+tau*D(label(c))/F(label(c)). Since tau<=1/2, this is at least tau*D(label(c))/F(label(c))>0. The coordinate bound is at most m/2, so a_tau(o)>=m/2>0. At either local endpoint of o, the sum Q(a_tau,c) contains a_tau(o), and all its other terms are positive. Hence a_tau(o)<=Q(a_tau,c)<1. These statements concern the same occurrence vector.")),
                    Paragraph(Text("Over the reals, the finite-product norm is the supremum norm. The nonnegative bound 3*tau*Dstar therefore gives ||a_tau-a0||_infinity<=3*tau*Dstar. For any epsilon>0, a single global parameter tau=min(1/2,m/(6*Dstar),epsilon/(6*Dstar)) is positive, obeys the required threshold, and gives distance at most epsilon/2<epsilon. Thus strict angles and strict corner inequalities can be achieved arbitrarily close to a0 in the same affine M-fiber if and only if every D(z)>0. The choice is global across all components.")),
                    Paragraph(Text("For rational initial data, instantiate the construction over the rational field itself. The finite fiber sizes, deficit sums, extrema, weights, integer path counts and half-coefficients all give a rational occurrence vector for every rational admissible tau. Cast that very vector to the reals. Casting commutes with the finite sums defining M and Q, so M_R(cast(a),e)=cast(M_Q(a,e)) and Q_R(cast(a),c)=cast(Q_Q(a,c)); it also preserves the displayed inequalities and deficit formula. Given a real epsilon>0, choose a positive rational tau smaller than min(1/2,cast(m)/(6*cast(Dstar)),epsilon/(6*cast(Dstar))). This gives the same strictification with real norm distance below epsilon, without extracting rational output from a real existence assertion.")),
                    Paragraph(Text("If T is empty, the occurrence, corner and both quotient domains are empty. The conditions on their coordinates and classes are vacuous, and a=a0 has norm distance zero for every positive epsilon, over both the real and rational constructions. No minimum m or maximum Dstar is assigned to an empty domain. An arbitrary coordinate bound on an empty domain, in particular a negative one, does not imply the same bound on the norm, which is zero.")),
                    Paragraph(Text("The complete linear image in Theorem 41.2 follows on these same occurrence and quotient carriers. Write S(h,z)=sum_{label(c)=z}h(c). The endpoint-multiset identity gives S(Q(a),z)=0 whenever M(a)=0. Conversely, for any signed real h with S(h,z)=0 for every z, put C=sum_c |h(c)| and d(c)=C+h(c). Then d is nonnegative and S(d,z)=F(z)*C. Apply the component averaging construction above with tau=1 and Dmax=sum_c d(c). Its single occurrence lift delta satisfies M(delta)=0 and -Q(delta,c)=C-d(c)=-h(c). Hence Q(ker M)=ker S, with no additional linear compatibility condition.")),
                    Paragraph(Text("The pinned finite-function pushforward FunOnFinite.linearMap is exactly M for P and exactly S for label. Both quotient maps are surjective; Finsupp.mapDomain_surjective and the finite-function linear equivalences therefore give surjectivity of M and S, including empty domains. Let t=|T|, e=|GlobalEdge(q)| and b=|Vertex(q)|. Additive rank-nullity gives e+dim ker M=6*t and b+dim ker S=4*t. The range of Q restricted to ker M is ker S. The existing restricted-kernel and subtype equivalences identify its kernel dimension with dim(ker M intersect ker Q), so e+dim(ker M intersect ker Q)=2*t+b. Equivalently the dimension is 2*t-e+b as an integer, or (2*t+b)-e with natural-number subtraction. The additive identity gives e<=2*t+b; it does not assert e<=2*t.")),
                    Paragraph(Text("The original face-transport supplement concerns the entire family F(i)=localLift(i)-localLift(J(i)), with all three corner choices on every paired face. Let X(i) be the difference of the two coordinate unit vectors at edge(i) and edge(J(i)). Reindexing the target face by its actual permutation gives F(x,r)=sum_s c(r,s)*X(x,s), where c(r,r)=1/2 and c(r,s)=-1/2 for distinct slots. The inverse identity is X(x,r)=F(x,r)-sum_s F(x,s). Thus these two exact families span the same subspace. Each X has M-image zero because the two actual paired-edge occurrences have the same P-label, so every F belongs to ker M.")),
                    Paragraph(Text("For the reverse span inclusion, let W be the span of the F vectors. Pull back the submodule quotient relation modulo W along the coordinate-unit-vector map. Every actual edgeRel generator belongs to this relation by the inverse identity, so Setoid.eqvGen_le implies that the unit-vector difference for any two occurrences with the same P-label belongs to W. Choose an actual representative r(e) of each global-edge class, and let R be its finite-function pushforward. Finite basis expansion gives a-R(M(a))=sum_o a(o)*(unit(o)-unit(r(P(o)))). For M(a)=0 this expresses a in W, proving that all original face transports span ker M. Self-gluing, repeated labels, loops and singleton fibers require no exceptions: identical occurrences give a zero difference, and all sums retain occurrence multiplicity. When T is empty, the spaces and both quotient carriers have dimension zero and the same statements hold.")),
                    Paragraph(Text("The transport and linear image, dimension and span applications assume no angle positivity, edge-degree bound, link-surface condition or common geometric length. The strictification application adds precisely the initial positivity, nonnegative deficit and positive component-total conditions above. The dimension counts real linear angle directions with fixed M and Q; it does not assert that arbitrary changes preserve angle inequalities. These results establish neither the link Euler identity, the minimum-degree conclusion of Theorem 42.2, nor compatibility of geometric edge lengths."))),
                DescribeRole.Theorem))));

    private static Formula Statement()
    {
        var q=F.Id("q"); var u=F.Id("u"); var v=F.Id("v");
        var w=F.Id("w"); var b=F.Id("B"); var s=F.Id("s"); var z=F.Id("z");
        var T=F.Id("T"); var S=F.Id("S"); var K=F.Id("K");
        var corner=Call("Corner",T);
        var same=All([("s",S)],Eq(Call("label",q,Apply(u,s)),Call("label",q,Apply(v,s))));
        var nonnegative=All([("s",S)],Le(F.D(0),Apply(w,s)));
        var bounded=All([("z",Call("Vertex",q))],Le(Call("mass",q,u,w,z),b));
        var premises=And(Call("Fintype",T),Call("Fintype",S),Call("Field",K),
            Call("LinearOrder",K),Call("IsStrictOrderedRing",K),same,nonnegative,bounded);
        return All([("T",F.Id("Type")),("S",F.Id("Type")),("K",F.Id("Type")),
            ("q",Call("Pairing",T)),("u",new Formula.TypeArrow(S,corner)),
            ("v",new Formula.TypeArrow(S,corner)),("w",new Formula.TypeArrow(S,K)),("B",K)],
            new Formula.Logic(premises,FormulaLogicOperator.Implies,Call("Transport",q,u,v,w,b)));
    }

    private static Formula All((string Name,Formula Type)[] vs,Formula body)=>
        new Formula.BindMany(FormulaQuantifier.ForAll,
            [..vs.Select(v=>new Formula.BoundVariable(FormulaIdentifier.Create(v.Name),v.Type))],body);
    private static Formula And(params Formula[] ps)
    {
        var result=ps[^1];
        for(var j=ps.Length-2;j>=0;j--) result=new Formula.Logic(ps[j],FormulaLogicOperator.And,result);
        return result;
    }
    private static Formula Eq(Formula a,Formula b)=>new Formula.Relation(a,FormulaRelationOperator.Equal,b);
    private static Formula Le(Formula a,Formula b)=>
        new Formula.Relation(a,FormulaRelationOperator.LessThanOrEqual,b);
    private static Formula Apply(Formula f,params Formula[] args)=>new Formula.Apply(f,[..args]);
    private static Formula Call(string name,params Formula[] args)=>Apply(F.Id(name),args);
}
